package app.multimin.ui;
import javax.swing.*;
import java.awt.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.Properties;
public final class LegalConsent {
 private static final String VERSION="2026-11-04";
 private static String read(String name){try(var in=LegalConsent.class.getResourceAsStream("/legal/"+name)){if(in==null)return "Document unavailable. Obtain the complete release before using capture.";return new String(in.readAllBytes(),StandardCharsets.UTF_8);}catch(Exception e){return "Document could not be read.";}}
 private static JTabbedPane documents(){JTabbedPane tabs=new JTabbedPane();for(String name:new String[]{"TERMS.md","PRIVACY.md"}){JTextArea text=new JTextArea(read(name),24,76);text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);text.setCaretPosition(0);tabs.add(name.equals("TERMS.md")?"User agreement":"Privacy notice",new JScrollPane(text));}return tabs;}
 public static void showDocuments(Component parent){JOptionPane.showMessageDialog(parent,documents(),"MultiMini agreement and privacy",JOptionPane.PLAIN_MESSAGE);}
 public static boolean ensureAccepted(){if(LegalConsent.class.getResource("/legal/TERMS.md")==null || LegalConsent.class.getResource("/legal/PRIVACY.md")==null){JOptionPane.showMessageDialog(null,"Agreement documents are missing. Please obtain the complete release.");return false;}Path path=WorkspaceStore.directory().resolve("agreement.properties");Properties p=new Properties();try(var in=Files.newInputStream(path)){p.load(in);if(VERSION.equals(p.getProperty("acceptedVersion")))return true;}catch(Exception ignored){}
  JDialog dialog=new JDialog((Frame)null,"Welcome to MultiMini",true);JPanel body=new JPanel(new BorderLayout(10,10));body.setBorder(BorderFactory.createEmptyBorder(16,16,16,16));body.add(new JLabel("Capture and input stay local. Workspaces are saved on this device. Updates contact GitHub only when requested."),BorderLayout.NORTH);body.add(documents(),BorderLayout.CENTER);JCheckBox agree=new JCheckBox("I have read and agree to the User Agreement and have read the Privacy Notice.");JButton accept=new JButton("Agree and continue"),decline=new JButton("Decline and exit");accept.setEnabled(false);agree.addActionListener(e->accept.setEnabled(agree.isSelected()));boolean[] result={false};accept.addActionListener(e->{try{Files.createDirectories(path.getParent());Properties record=new Properties();record.setProperty("acceptedVersion",VERSION);record.setProperty("acceptedAt",java.time.Instant.now().toString());try(var out=Files.newOutputStream(path)){record.store(out,"MultiMini local agreement acceptance");}result[0]=true;dialog.dispose();}catch(Exception error){JOptionPane.showMessageDialog(dialog,"Could not save acceptance: "+error.getMessage());}});decline.addActionListener(e->dialog.dispose());JPanel bottom=new JPanel(new BorderLayout());bottom.add(agree,BorderLayout.NORTH);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));buttons.add(decline);buttons.add(accept);bottom.add(buttons,BorderLayout.SOUTH);body.add(bottom,BorderLayout.SOUTH);dialog.setContentPane(body);dialog.pack();dialog.setLocationRelativeTo(null);dialog.setVisible(true);return result[0];
 }
}
